def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Recolor every monochromatic full row or column to 2.
    for r in range(h):
        if all(grid[r][c] == grid[r][0] for c in range(w)):
            out[r] = [2] * w
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            for r in range(h):
                out[r][c] = 2
    return out
